userDefinedLinkHintCss:
div > .vimiumHintMarker {
  background: #7dd3fc;
  border: 2px solid #0369a1;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(3, 105, 161, 0.45);
  padding: 4px 7px;
}

div > .vimiumHintMarker span {
  color: #082f49;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.2;
  text-shadow: none;
}

div > .vimiumHintMarker > .matchingCharacter {
  color: #075985;
}
